// Dictionnaire codé en dur pour les 6 langues les plus demandées (aucun
// appel réseau, traduction instantanée). Pour les ~110 autres langues
// proposées dans les paramètres, initAutoTranslate() (plus bas) prend le
// relais : traduction automatique de TOUT le texte d'interface visible à
// l'écran (boutons, menus, titres, info-bulles…), à la volée et mise en
// cache — voir /api/i18n/translate côté Worker. Le contenu que les gens
// écrivent eux-mêmes (messages, pseudos, statuts, bios) n'est volontairement
// JAMAIS traduit automatiquement, comme sur Discord ou WhatsApp.
function t(key,fallback){
  const lang=(appPrefs&&appPrefs.language)||'fr';
  const dict=I18N[lang]||I18N.fr;
  return dict[key]||I18N.fr[key]||fallback||key;
}
function applyI18n(){
  try{document.documentElement.lang=(appPrefs&&appPrefs.language)||'fr';}catch(e){}
  document.querySelectorAll('[data-i18n]').forEach(function(el){el.textContent=t(el.getAttribute('data-i18n'));});
  document.querySelectorAll('[data-i18n-title]').forEach(function(el){el.title=t(el.getAttribute('data-i18n-title'));});
  document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){el.placeholder=t(el.getAttribute('data-i18n-placeholder'));});
  if(typeof initAutoTranslate==='function')initAutoTranslate();
}
/* ===== Traduction automatique de l'interface (langues au-delà des 6 du
   dictionnaire codé en dur) — voir /api/i18n/translate côté Worker pour la
   partie serveur (appel IA + cache KV partagé). Parcourt #app et #stage
   (l'app connectée ET l'écran de connexion) nœud texte par nœud texte, en
   sautant explicitement tout ce qui est du contenu écrit par les gens
   eux-mêmes (atDenySelector) plutôt que du texte d'interface fixe — ce
   n'est pas une limitation, c'est le comportement correct : personne ne
   veut que ses messages privés ou son pseudo soient retraduits sans le
   demander.
   Anti-boucle : un MutationObserver qui traduit du texte DÉCLENCHE
   forcément de nouvelles mutations (celles qu'il vient de créer). On évite
   la boucle infinie en gardant, par nœud texte (WeakMap — jamais de fuite
   mémoire, le nœud disparaît du DOM sans laisser de trace), la langue et le
   texte de SORTIE de la dernière traduction appliquée : si le texte actuel
   du nœud est déjà exactement cette sortie, on ne fait rien. */
let autoTranslateObserver=null;
const AT_NODE_STATE=new WeakMap();
// script/style/noscript/template EN PREMIER : un TreeWalker(SHOW_TEXT) ne
// connaît pas la sémantique HTML — sans cette exclusion explicite, un
// parcours sur document.body descendrait aussi dans le texte des balises
// de script (le code source de l'appli elle-même, plus d'un million de
// caractères) et tenterait de le "traduire" comme n'importe quel texte
// visible. Repéré en relisant le code avant déploiement, jamais vu en
// production, mais aurait été un vrai désastre.
const AT_DENY_SELECTOR_BASE='script, style, noscript, template, .bub, .row .info .n, .row .info .p, .userbar .n, .pc-custom-status, .rp-name, .rp-tag, pre, code, [contenteditable], [data-i18n-skip], input, textarea, .msgs .msg, .cr-textchat-panel .msgs, .lang-opt, .emoji-picker-pop, .qr-login-frame, .cvs-tile-name, .gcb-vtile-name, .gcb-p-name, .srv-voice-member-name, .svc-present-name, .srv-item-name, .srv-item-sub, .srv-chan-name, .srv-detail-desc, .srv-cat-label';
// Bug remonté ("plein de langues qui ne fonctionnent pas") : les éléments
// [data-i18n]/[data-i18n-title]/[data-i18n-placeholder] étaient TOUJOURS
// exclus de l'auto-traduction — correct pour les 6 langues qui ont un vrai
// dictionnaire (I18N ci-dessus), puisqu'ils reçoivent déjà la bonne
// traduction via t(). Mais pour les ~110 AUTRES langues, I18N[lang]
// n'existe pas : t() retombe alors sur I18N.fr (français, voir sa
// définition plus haut) — ces éléments restaient donc bloqués en français
// pour toujours dans TOUTE langue non couverte par le dictionnaire,
// puisqu'exclus ici de la traduction automatique qui aurait pu les
// rattraper. Ne les exclure QUE quand la langue courante a vraiment un
// dictionnaire complet.
function atDenySelector(lang){
  return I18N[lang]?(AT_DENY_SELECTOR_BASE+', [data-i18n], [data-i18n-title], [data-i18n-placeholder]'):AT_DENY_SELECTOR_BASE;
}
let atTranslationMemory={};
function atLoadMemory(lang){
  if(atTranslationMemory[lang])return atTranslationMemory[lang];
  let mem={};
  try{mem=JSON.parse(localStorage.getItem('xultra_i18n_cache_'+lang)||'{}')||{};}catch(e){mem={};}
  atTranslationMemory[lang]=mem;
  return mem;
}
function atSaveMemory(lang){
  try{
    const mem=atTranslationMemory[lang]||{};
    // Borne la taille du cache local — au-delà de ~2000 entrées on repart de
    // zéro plutôt que de gérer une éviction LRU : ce cache n'est qu'une
    // optimisation de confort (le cache serveur KV, partagé entre tout le
    // monde, reste la source de vérité et évite de re-payer l'IA).
    if(Object.keys(mem).length>2000){atTranslationMemory[lang]={};return;}
    localStorage.setItem('xultra_i18n_cache_'+lang,JSON.stringify(mem));
  }catch(e){}
}
let atPendingQueue=[],atFlushTimer=null;
function atQueueTranslate(text,lang,cb){
  const mem=atLoadMemory(lang);
  if(mem[text]!=null){cb(mem[text]);return}
  atPendingQueue.push({text:text,lang:lang,cb:cb});
  if(atFlushTimer)clearTimeout(atFlushTimer);
  if(atPendingQueue.length>=40)atFlushQueue();
  else atFlushTimer=setTimeout(atFlushQueue,250);
}
function atFlushQueue(){
  if(atFlushTimer){clearTimeout(atFlushTimer);atFlushTimer=null;}
  if(!atPendingQueue.length)return;
  const batch=atPendingQueue.splice(0,50);
  const lang=batch[0].lang;
  const sameLang=batch.filter(function(e){return e.lang===lang;});
  const rest=batch.filter(function(e){return e.lang!==lang;});
  if(rest.length)atPendingQueue=rest.concat(atPendingQueue);
  const uniqueTexts=Array.from(new Set(sameLang.map(function(e){return e.text;})));
  fetch('/api/i18n/translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({texts:uniqueTexts,targetLang:lang})})
    .then(function(r){return r.json();})
    .then(function(j){
      const translations=(j&&j.translations)||{};
      const mem=atLoadMemory(lang);
      // Comme côté serveur (voir /api/i18n/translate) : ne jamais figer dans le
      // cache local une "traduction" identique au texte source — un lot entier
      // parti en échec (réponse serveur vide/erreur) resterait sinon collé en
      // français dans localStorage pour toujours, sans jamais réessayer.
      uniqueTexts.forEach(function(txt){
        const out=translations[txt]||txt;
        if(out!==txt)mem[txt]=out;
      });
      atSaveMemory(lang);
      sameLang.forEach(function(e){e.cb(translations[e.text]||e.text);});
    })
    .catch(function(){sameLang.forEach(function(e){e.cb(e.text);});});
  if(atPendingQueue.length)atFlushTimer=setTimeout(atFlushQueue,250);
}
function atLooksTranslatable(text){
  if(!text)return false;
  const trimmed=text.trim();
  if(trimmed.length<2)return false;
  if(!/\\p{L}/u.test(trimmed))return false;
  return true;
}
function atProcessNode(node,lang){
  const parent=node.parentElement;
  if(!parent||parent.closest(atDenySelector(lang)))return;
  const state=AT_NODE_STATE.get(node);
  // Bug remonté : changer de langue plusieurs fois de suite (ex. es -> en ->
  // es) traduisait mal ou pas du tout. Cause : le code lisait node.nodeValue
  // comme "texte source", mais après une première traduction, nodeValue
  // n'est déjà PLUS le français d'origine — c'est la traduction précédente.
  // Un deuxième changement de langue demandait donc à l'IA de traduire une
  // traduction, avec source_lang toujours annoncé "fr" côté serveur alors
  // que ce n'était souvent plus vrai (m2m100 est un modèle de traduction
  // dédié, pas un LLM — un mauvais tag de langue source lui fait produire du
  // charabia). Et le cache (local + KV serveur), qui indexe par texte
  // source, ratait alors systématiquement les langues déjà visitées
  // (indexées sous le vrai français) puisqu'on cherchait sous la mauvaise
  // clé — nouvel appel IA à chaque fois, jamais de cache hit, jamais
  // "instantané". Fix : le texte source d'origine (français) est figé une
  // bonne fois pour toutes au tout premier passage sur ce nœud, et reste la
  // seule chose jamais envoyée à traduire, quel que soit ce que nodeValue
  // affiche au moment où on change à nouveau de langue.
  const origSrc=state?state.origSrc:node.nodeValue;
  if(!atLooksTranslatable(origSrc))return;
  if(state&&state.lang===lang&&(state.out===node.nodeValue||state.pending))return;
  const newState={lang:lang,origSrc:origSrc,out:null,pending:true};
  AT_NODE_STATE.set(node,newState);
  atQueueTranslate(origSrc,lang,function(translated){
    if(!node.isConnected)return;
    // Comparaison par identité de state (pas par texte) : si un changement de
    // langue plus récent a déjà pris le relais sur ce nœud entre-temps, cette
    // réponse arrivée en retard ne doit pas l'écraser.
    if(AT_NODE_STATE.get(node)!==newState)return;
    newState.out=translated;newState.pending=false;
    node.nodeValue=translated;
  });
}
// Bug remonté ("certains trucs pas du tout traduits") : jusqu'ici seul le
// TEXTE VISIBLE (nœuds texte) passait par l'auto-traduction — les ~280
// attributs title="…"/placeholder="…"/aria-label="…" codés en dur en
// français dans toute l'appli (infobulles, champs de recherche/saisie…)
// n'étaient JAMAIS traduits, dans AUCUNE langue, pas même les 6 du
// dictionnaire. Même mécanique que atProcessNode (texte source figé au
// premier passage, jamais retraduit à partir d'une traduction précédente),
// appliquée à un attribut au lieu d'un nœud texte.
const AT_ATTR_STATE=new WeakMap();
const AT_ATTRS=['title','placeholder','aria-label'];
function atProcessAttr(el,attr,lang){
  if(!el||!el.hasAttribute||!el.hasAttribute(attr))return;
  if(el.closest&&el.closest(atDenySelector(lang)))return;
  let byAttr=AT_ATTR_STATE.get(el);
  const prev=byAttr&&byAttr[attr];
  const origSrc=prev?prev.origSrc:el.getAttribute(attr);
  if(!atLooksTranslatable(origSrc))return;
  if(prev&&prev.lang===lang&&(prev.out===el.getAttribute(attr)||prev.pending))return;
  const entry={lang:lang,origSrc:origSrc,out:null,pending:true};
  if(!byAttr){byAttr={};AT_ATTR_STATE.set(el,byAttr);}
  byAttr[attr]=entry;
  atQueueTranslate(origSrc,lang,function(translated){
    if(!el.isConnected)return;
    const cur=AT_ATTR_STATE.get(el);
    if(!cur||cur[attr]!==entry)return;
    entry.out=translated;entry.pending=false;
    el.setAttribute(attr,translated);
  });
}
function atScanAttrs(root,lang){
  AT_ATTRS.forEach(function(attr){
    if(root.nodeType===1&&root.hasAttribute&&root.hasAttribute(attr))atProcessAttr(root,attr,lang);
    if(root.querySelectorAll){
      root.querySelectorAll('['+attr+']').forEach(function(el){atProcessAttr(el,attr,lang);});
    }
  });
}
// mode:'open' uniquement (pages de guilde personnalisées, voir
// buildGuildPageHtml/openGuildPage) : un shadowRoot bloque normalement tout
// TreeWalker/MutationObserver posé sur le document — sans ce détour
// explicite, ce contenu restait figé en français quelle que soit la langue.
function atScan(root,lang){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,null);
  let node;
  while((node=walker.nextNode()))atProcessNode(node,lang);
  atScanAttrs(root,lang);
  if(root.querySelectorAll){
    root.querySelectorAll('*').forEach(function(el){
      if(el.shadowRoot)atScan(el.shadowRoot,lang);
    });
  }
}
function initAutoTranslate(){
  if(MULTILANG_PAUSED){
    if(autoTranslateObserver){autoTranslateObserver.disconnect();autoTranslateObserver=null;}
    return;
  }
  const lang=(appPrefs&&appPrefs.language)||'fr';
  // 'fr' est la langue SOURCE de toutes les chaînes codées en dur — jamais
  // rien à traduire dans ce cas, contrairement aux 5 autres langues du
  // dictionnaire codé en dur (en/es/pt/de/it) : leur dictionnaire ne couvre
  // qu'un socle d'une quarantaine de clés (nav, écran de connexion, titres
  // de réglages) — tout le reste du site (panneaux de paramètres, modales,
  // conversations, salons de serveur…) a besoin d'auto-traduction tout
  // autant qu'une langue "non couverte". Les éléments [data-i18n] sont
  // exclus (voir atDenySelector) UNIQUEMENT pour ces 6 langues, puisqu'ils
  // reçoivent déjà la traduction exacte du dictionnaire — inutile et
  // parfois contre-productif de les repasser aussi par l'IA. Pour toute
  // autre langue, ils sont au contraire scannés comme le reste (voir
  // atDenySelector plus haut) : sans dictionnaire, ils resteraient sinon
  // bloqués en français pour toujours.
  if(lang==='fr'){
    if(autoTranslateObserver){autoTranslateObserver.disconnect();autoTranslateObserver=null;}
    return;
  }
  // document.body, pas juste #app/#stage : la quasi-totalité des modales et
  // panneaux du site (paramètres, profil, signalement, consentement OAuth,
  // approbation QR…) sont des enfants DIRECTS de <body>, PAS de #app —
  // s'en tenir à #app/#stage laissait tout ce qui s'affiche en overlay
  // intégralement en français, quelle que soit la langue choisie (bug
  // remonté par un utilisateur : "le site reste toujours en français").
  atScan(document.body,lang);
  if(autoTranslateObserver)autoTranslateObserver.disconnect();
  autoTranslateObserver=new MutationObserver(function(mutations){
    const curLang=(appPrefs&&appPrefs.language)||'fr';
    if(curLang==='fr')return;
    const roots=new Set();
    mutations.forEach(function(m){
      if(m.type==='characterData')atProcessNode(m.target,curLang);
      else if(m.type==='attributes'&&AT_ATTRS.indexOf(m.attributeName)>=0)atProcessAttr(m.target,m.attributeName,curLang);
      else if(m.type==='childList'){
        m.addedNodes.forEach(function(n){
          if(n.nodeType===3)atProcessNode(n,curLang);
          else if(n.nodeType===1)roots.add(n);
        });
      }
    });
    roots.forEach(function(r){atScan(r,curLang);});
  });
  autoTranslateObserver.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:AT_ATTRS});
}

function applyAppPrefs(){
  try{document.documentElement.style.setProperty('--msg-font-size',appPrefs.msgFontSize+'px');}catch(e){}
  try{document.documentElement.style.setProperty('--msg-gap',appPrefs.msgSpacing==='compact'?'4px':'10px');}catch(e){}
  if(document.body){
    try{
      const zf=(appPrefs.zoomScale||100)/100;
      document.body.style.zoom=zf;
      /* #app a une hauteur fixe de 100dvh : la propriété CSS zoom() la
         rétrécit visuellement avec tout le reste (contrairement à un
         transform:scale, mais les unités dvh restent calculées sur le
         vrai viewport), ce qui laisse une bande noire en bas dès qu'on
         dézoome (<100%). On compense en gonflant la hauteur avant zoom
         d'un facteur inverse, pour qu'elle retombe pile sur 100dvh une
         fois le zoom appliqué. */
      document.documentElement.style.setProperty('--zoom-factor',String(zf||1));
    }catch(e){}
    document.body.classList.toggle('compact-mode',appPrefs.displayMode==='compact');
    document.body.classList.toggle('no-emoji-anim',!appPrefs.animateEmoji);
    document.body.classList.toggle('reduce-motion',!!appPrefs.reduceMotion);
    document.body.classList.toggle('high-contrast',!!appPrefs.highContrast);
    document.body.classList.toggle('gif-hover-mode',!!appPrefs.gifHoverPlay);
    applyThemeMode();
  }
  applyI18n();
}
function applyThemeMode(){
  if(!document.body)return;
  const mode=appPrefs.theme||'dark';
  let isLight=false;
  if(mode==='light')isLight=true;
  else if(mode==='system'){
    try{isLight=window.matchMedia('(prefers-color-scheme: light)').matches;}catch(e){isLight=false;}
  }
  document.body.classList.toggle('theme-light',isLight);
  document.body.classList.toggle('theme-oled',mode==='oled');
  document.body.classList.toggle('theme-mono',mode==='mono');
}
try{
  window.matchMedia('(prefers-color-scheme: light)').addEventListener('change',function(){if(appPrefs.theme==='system')applyThemeMode();});
}catch(e){}
applyAppPrefs();
