      const dm = await awFetch("/databases/" + AW_DB + "/collections/dms/documents/" + dmId, { asAdmin: true });
      const members = (dm.members || []).map(String);
      if (members.indexOf(String(acc.$id)) < 0) throw new Error("Tu n'es pas membre de ce groupe");
