      const updated = await awFetch("/databases/" + AW_DB + "/collections/servers/documents/" + serverId, { method: "PATCH", asAdmin: true, body: { data: { inviteCode: code } } });
      const actorProfileVanity = await resolveProfile(acc.$id);
